/**
 * Deterministic module title lookup with a safe fallback — mirrors the
 * same MODULE_NAMES map used by quiz.ts/caseStudies.ts, imported
 * lazily inside the function to avoid a circular import at module
 * load time (agents.ts also exports MODULE_NAMES).
 */
export function offlineFallbackQuiz(moduleNum: number, moduleTitle: string): { module_title: string; questions: QuizQuestion[] } | null {
  const entry = QUESTION_BANK[moduleNum];
  if (!entry) return null;
  return { module_title: moduleTitle, questions: [entry.quiz] };
}

export function offlineFallbackCase(moduleNum: number, moduleTitle: string): { module_title: string; cases: CaseStudy[] } | null {
  const entry = QUESTION_BANK[moduleNum];
  if (!entry) return null;
  return { module_title: moduleTitle, cases: [entry.caseStudy] };
}
